c='p4';B='MẠNG 4A'
S=[]
S.append(TITLE('TIN HỌC · MẠNG 4A','CHIA SẺ TÀI NGUYÊN<br>VÀ AN TOÀN MẠNG','Chia sẻ thư mục và máy in trong LAN Windows, mạng Private – Public, tường lửa, lừa đảo, 2FA và sao lưu.',['chia sẻ','Private – Public','tường lửa','2FA','sao lưu']))
S.append(goals(c,B,['Nêu <b>điều kiện</b> để chia sẻ <b>thư mục, máy in</b> trong LAN.','Cấu hình đúng: <b>Network discovery</b>, chia sẻ tệp – máy in, mạng <b>Private</b>.','Hiểu <b>thư mục Public</b> và <b>tường lửa</b>.','Nhận biết <b>lừa đảo trực tuyến</b>; hiểu <b>2FA</b>; biết cách <b>sao lưu</b> an toàn.','Phân biệt hai mô hình <b>workgroup</b> và <b>domain</b>.'],['Chia sẻ tệp','Chia sẻ máy in','Tường lửa','An toàn thông tin','Workgroup – domain']))
